import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import prisma from '@/lib/prisma'

describe('POST /api/bookmarks', () => {
  it('creates and returns a bookmark', async () => {
    const response = await fetch('http://localhost:3000/api/bookmarks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        lessonSlug: 'component-testing-vs-integration-testing',
        courseSlug: 'react-testing',
      }),
    })

    const bookmark = await response.json()
    expect(response.status).toBe(201)
    expect(bookmark.lessonSlug).toBe('component-testing-vs-integration-testing')

    const inDb = await prisma.bookmark.findUnique({
      where: { id: bookmark.id },
    })
    expect(inDb).toBeDefined()
  })
})
